source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    dirs4 = ((1,0),(-1,0),(0,1),(0,-1))
    dirs8 = tuple((dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc)

    # Label 4-connected lines and background regions.
    line_id = [[-1]*w for _ in range(h)]
    lines = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or line_id[r][c] >= 0:
                continue
            k = len(lines); line_id[r][c] = k
            q = deque([(r,c)]); cells = []
            while q:
                y,x = q.popleft(); cells.append((y,x))
                for dy,dx in dirs4:
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==1 and line_id[yy][xx]<0:
                        line_id[yy][xx]=k; q.append((yy,xx))
            lines.append(cells)

    bg_id = [[-1]*w for _ in range(h)]
    backgrounds = []
    exterior = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or bg_id[r][c] >= 0:
                continue
            k=len(backgrounds); bg_id[r][c]=k; q=deque([(r,c)]); cells=[]; edge=False
            while q:
                y,x=q.popleft(); cells.append((y,x))
                if y==0 or x==0 or y==h-1 or x==w-1: edge=True
                for dy,dx in dirs4:
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and bg_id[yy][xx]<0:
                        bg_id[yy][xx]=k; q.append((yy,xx))
            backgrounds.append(cells); exterior.append(edge)

    # A line component is active when it borders an enclosed background pocket.
    active=set()
    for k,cells in enumerate(backgrounds):
        if exterior[k]:
            continue
        for y,x in cells:
            for dy,dx in dirs4:
                yy,xx=y+dy,x+dx
                if 0<=yy<h and 0<=xx<w and line_id[yy][xx]>=0:
                    active.add(line_id[yy][xx])

    # Color the one-cell (8-neighbor) shell on the inside and outside of active outlines.
    for k,cells in enumerate(backgrounds):
        if not cells:
            continue
        if exterior[k]:
            color=2
            if not active:
                continue
        else:
            color=3
        for y,x in cells:
            near_active=False
            for dy,dx in dirs8:
                yy,xx=y+dy,x+dx
                if 0<=yy<h and 0<=xx<w and line_id[yy][xx] in active:
                    near_active=True; break
            if near_active:
                out[y][x]=color
    return out
'''
